// Health + heartbeat check. Runs every 15 minutes.
// Input: rows from "Automations" (Name, Every Minutes, Active From, Active To, Mode)
//        and "Automation Log" (Timestamp, Automation, Result, Attempt, Items, Error, Note).
// Output: one item with { hasProblems, problems[], message }.
// Static data remembers what we already alerted on, so a person gets ONE text per problem,
// not one every 15 minutes.

const GRACE_MIN = 5;
const now = new Date();
const automations = $('Read automations list').all().map(i => i.json);
const log = $('Read automation log').all().map(i => i.json);
const seen = $getWorkflowStaticData('global');
seen.alerted = seen.alerted || {};

const mins = v => { const [h, m] = String(v || '0:0').split(':').map(Number); return h * 60 + (m || 0); };
function lastExpected(a) {
  const every = Number(a['Every Minutes']);
  if (!every) return null;
  const t = new Date(now.getTime() - GRACE_MIN * 60000);
  const m = t.getHours() * 60 + t.getMinutes();
  const from = mins(a['Active From'] || '00:00'), to = mins(a['Active To'] || '23:59');
  if (m < from) return null;
  const slot = Math.min(to, from + Math.floor((m - from) / every) * every);
  const d = new Date(t); d.setHours(0, slot, 0, 0);
  return d;
}

const problems = [];
for (const a of automations) {
  const mode = String(a.Mode || 'live').toLowerCase();
  if (mode === 'paused' || mode === 'shadow') continue;     // paused: not checked; shadow: logging only
  const runs = log.filter(r => r.Automation === a.Name).sort((x, y) => new Date(x.Timestamp) - new Date(y.Timestamp));
  const last = runs[runs.length - 1];
  const lastAt = last ? new Date(last.Timestamp) : null;

  // 1) Retries exhausted (attempt 4 = 1 run + 3 retries)
  if (last && last.Result === 'failed' && Number(last.Attempt) >= 4) {
    problems.push({ key: a.Name + '|failed|' + last.Timestamp, automation: a.Name, kind: 'failed',
      text: a.Name + ' failed after 3 retries: ' + last.Error + '. Held items stay queued until the next good run.' });
    continue;
  }
  // 2) Heartbeat: should have run by now but didn't (silent stop)
  const expected = lastExpected(a);
  if (expected && (!lastAt || lastAt < expected)) {
    problems.push({ key: a.Name + '|late|' + (lastAt ? lastAt.toISOString() : 'never'), automation: a.Name, kind: 'late',
      text: a.Name + ': no run since ' + (lastAt ? lastAt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : 'ever') +
            ', expected every ' + a['Every Minutes'] + ' min.' });
  }
}

const fresh = problems.filter(p => !seen.alerted[p.key]);
fresh.forEach(p => { seen.alerted[p.key] = now.toISOString(); });
// Forget alerts older than 3 days so static data stays small
for (const [k, t] of Object.entries(seen.alerted)) if (now - new Date(t) > 3 * 864e5) delete seen.alerted[k];

return [{ json: {
  checkedAt: now.toISOString(),
  hasProblems: fresh.length > 0,
  problems: fresh,
  stillOpen: problems.length,
  message: fresh.map(p => '- ' + p.text).join('\n'),
} }];

