// Builds the 6:30 AM digest from the Jobs sheet and the last 24 h of the run log.
const FIRST_CALL_HOURS = { 'Northstar Home Warranty': 24, 'Bluepeak Protection Plans': 48, 'Harbor Appliance Care': 24, 'Direct customer': 4 };
const DONE = ['completed', 'invoiced', 'cancelled'];
const now = new Date();
const jobs = $('Read jobs').all().map(i => i.json);
const log = $('Read run log').all().map(i => i.json).filter(r => now - new Date(r.Timestamp) < 864e5);
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const overdue = jobs
  .filter(j => !DONE.includes(String(j.Status).toLowerCase()) && !j['First Call At'])
  .map(j => ({ ...j, due: new Date(new Date(j['Created At']).getTime() + (FIRST_CALL_HOURS[j.Vendor] || 24) * 36e5) }))
  .filter(j => j.due < now)
  .sort((a, b) => a.due - b.due);

const names = [...new Set(log.map(r => r.Automation))].sort();
const health = names.map(n => {
  const rs = log.filter(r => r.Automation === n);
  const failed = rs.filter(r => r.Result === 'failed').length;
  const recovered = rs.filter(r => r.Result === 'recovered').length;
  const last = rs[rs.length - 1];
  const status = last && last.Result === 'failed' && Number(last.Attempt) >= 4 ? 'FAILED' : 'OK';
  return { n, status, line: rs.length + ' runs, ' + failed + ' failed attempts, ' + recovered + ' fixed on retry' };
});
const problems = health.filter(h => h.status !== 'OK').length;
const headline = problems ? problems + ' automation' + (problems > 1 ? 's need' : ' needs') + ' attention' : 'All systems normal';
const subject = 'Summit daily digest · ' + now.toDateString() + ' · ' + headline + (overdue.length ? ' · ' + overdue.length + ' overdue first calls' : '');

const row = (l, r) => '<tr><td style="padding:8px 0;border-top:1px solid #e6e9e3;font:14px Arial,sans-serif;">' + l + '</td><td style="padding:8px 0;border-top:1px solid #e6e9e3;font:13px Arial,sans-serif;color:#55605b;text-align:right;">' + r + '</td></tr>';
const html = '<div style="background:#eceee8;padding:16px 8px;"><div style="max-width:600px;margin:auto;background:#fff;border-radius:12px;padding:22px 26px;font-family:Arial,sans-serif;">'
  + '<div style="font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#0f7a5c;font-weight:bold;">Summit Home Services · Daily digest</div>'
  + '<h1 style="font-size:20px;color:' + (problems ? '#a1281c' : '#0f6b51') + ';">' + esc(headline) + '</h1>'
  + '<h2 style="font-size:15px;">Overdue first calls (' + overdue.length + ')</h2><table width="100%" cellspacing="0">'
  + overdue.map(j => row('<b>' + esc(j['Job ID']) + '</b> ' + esc(j.Customer) + ' · ' + esc(j.Vendor), Math.round((now - j.due) / 36e5) + ' h late')).join('')
  + '</table><h2 style="font-size:15px;">Automation health, last 24 h</h2><table width="100%" cellspacing="0">'
  + health.map(h => row('<b>' + esc(h.n) + '</b><br><span style="color:#55605b;font-size:13px;">' + esc(h.line) + '</span>', h.status)).join('')
  + '</table><p style="font-size:12px;color:#6b7570;">Sent by Summit Ops Bot. If this has not arrived by 7:00 AM, Ted gets a text.</p></div></div>';
const text = [subject, '', 'OVERDUE FIRST CALLS', ...overdue.map(j => '* ' + j['Job ID'] + ' ' + j.Customer + ' (' + j.Vendor + ')'), '', 'AUTOMATION HEALTH', ...health.map(h => '[' + h.status + '] ' + h.n + ': ' + h.line)].join('\n');

return [{ json: { subject, html, text, overdue: overdue.length, problems } }];

// Shadow mode: the digest is built but not sent. Check the execution data, then set shadowMode to false.
console.log('[SHADOW] ' + $json.subject + '\n' + $json.text);
return { json: { result: 'shadow', note: 'Digest built, not sent (shadow mode)', subject: $json.subject } };
